import requests
from taf.ue.tm500.rtc.exceptions import RtcOperationFailed, RtcParameterError
from os.path import isabs
from urllib3.util.retry import Retry
from requests.adapters import HTTPAdapter
import ntpath


class RtcConnection:

    def __init__(self, ip, port=5099, tma_id='0001'):
        self._base_url = 'http://{}:{}/rtc'.format(ip, port)
        self.tma_id = tma_id
        self.session = requests.Session()
        self.session.trust_env = False
        retry_strategy = Retry(
            total=3,
            backoff_factor=10,
            status_forcelist=[429, 500, 502, 503, 504, 404],
            # 429, 404 these are E500 specific exceptions that had to be added.
            method_whitelist=["POST", "GET", "DELETE"],
            raise_on_status=False
        )
        adapter = HTTPAdapter(max_retries=retry_strategy)
        self.session.mount("http://", adapter)

    def post(self, rel, body=None):
        result = None
        try:
            if body:
                result = self.session.post(url=self._base_url + rel,
                                           json=body, timeout=60)
            else:
                result = self.session.post(url=self._base_url + rel,
                                           timeout=60)
            result.raise_for_status()
        except requests.exceptions.HTTPError as e:
            raise RtcOperationFailed(e, result.text)
        except Exception as e:
            raise RtcOperationFailed(e, 'Post request failed')
        return result.text

    def get(self, rel, body=None):
        result = None
        try:
            result = self.session.get(url=self._base_url + rel,
                                      timeout=60)
            result.raise_for_status()
        except requests.exceptions.HTTPError as e:
            raise RtcOperationFailed(e, result.text)
        except Exception as e:
            raise RtcOperationFailed(e, 'Get request failed')
        return result.text

    def delete(self, rel, body=None):
        result = None
        try:
            result = self.session.delete(url=self._base_url + rel,
                                         timeout=60)
            result.raise_for_status()
        except requests.exceptions.HTTPError as e:
            raise RtcOperationFailed(e, result.text)
        except Exception as e:
            raise RtcOperationFailed(e, 'Delete request failed')
        return result.text

    def open_the_tma_in_given_mode(self, tma_type=1, tma_path=None, mci_port=None,
                                   aci_port=None, tma_profile=None):
        rel = '/tmas'
        body = {}
        body.update({'TMA_TYPE': tma_type})
        if tma_path:
            if tma_path and ntpath.isabs(tma_path):
                body.update({'TMA_PATH': tma_path})
            else:
                raise RtcParameterError('TMA_PATH failed: {}'.format(tma_path))
        if mci_port and int(mci_port):
            body.update({'MCI_PORT': int(mci_port)})
        if aci_port and int(aci_port):
            body.update({'ACI_PORT': int(aci_port)})
        if tma_profile:
            body.update({'TMA_PROFILE': str(tma_profile)})
        result = self.post(rel, body)
        return result

    def close_the_tma(self):
        rel = '/tmas/{}'.format(self.tma_id)
        result = self.delete(rel)
        return result

    def close_all_instances_of_tma(self):
        rel = '/tmas'
        result = self.delete(rel)
        return result

    def get_all_opened_tmas(self):
        rel = '/tmas'
        result = self.get(rel)
        return result.split(',')

    def get_path_to_tma_executable(self):
        rel = '/tmas/{}'.format(self.tma_id)
        result = self.get(rel)
        return result

    def schedule_campaign(self, campaign_path, iteration_count=1, action_on_event=2,
                          date=None, time=None):
        rel = '/tmas/{}/campaigns/actions/schedule'.format(self.tma_id)
        body = {}
        if campaign_path and ntpath.isabs(campaign_path):
            body.update({'FILE_PATH': campaign_path})
        else:
            raise RtcParameterError('Campaign path failed: {}'.format(campaign_path))
        if iteration_count and int(iteration_count):
            body.update({'ITERATION_COUNT': iteration_count})
        if action_on_event and int(action_on_event):
            body.update({'ACTION_ON_EVENT': action_on_event})
        if date and str(date):
            body.update({'DATE': date})
        if time and str(time):
            body.update({'TIME': time})
        result = self.post(rel, body)
        return result

    def run_a_scheduled_e500_campaign(self, campaign_name, add_to_active_scheduler=None):
        rel = '/tmas/{}/campaigns/actions/run'.format(self.tma_id)
        body = {}
        body.update({'CAMPAIGN_NAME': campaign_name})
        if add_to_active_scheduler in [1, 2]:
            body.update({'ADD_TO_ACTIVE_SCHEDULER': add_to_active_scheduler})
        result = self.post(rel, body)
        return result

    def provide_running_state_of_campaign_run(self):
        rel = '/tmas/{}/campaigns/actions/run'.format(self.tma_id)
        result = self.get(rel)
        return result

    def stop_a_running_e500_campaign(self):
        rel = '/tmas/{}/campaigns/actions/stop'.format(self.tma_id)
        result = self.post(rel)
        return result

    def execute_mci_command(self, cmd, cmd_timeout=2):
        rel = '/tmas/{}/campaigns/actions/executecommand'.format(self.tma_id)
        body = {}
        if cmd and str(cmd):
            body.update({'MCI_COMMAND': cmd})
        if cmd_timeout and int(cmd_timeout):
            body.update({'CMD_TIMEOUT': cmd_timeout})
        result = self.post(rel, body)
        return result

    def generate_report_of_executed_campaign(self, campaign_name):
        rel = '/tmas/{}/campaigns/actions/generatereport'.format(self.tma_id)
        body = {}
        body.update({'CAMPAIGN_NAME': campaign_name})
        result = self.post(rel, body)
        return result

    def get_report_generation_progress(self):
        rel = '/tmas/{}/campaigns/actions/generatereport'.format(self.tma_id)
        result = self.get(rel)
        return result

    def schedule_and_start_test_run_on_extmue(self, campaign_path, iteration_count=1, action_on_event=2,
                                              date=None, time=None):

        rel = '/tmas/{}/tests/actions/run'.format(self.tma_id)
        body = {}
        if campaign_path and isabs(campaign_path):
            body.update({'FILE_PATH': campaign_path})
        if iteration_count and int(iteration_count):
            body.update({'ITERATION_COUNT': iteration_count})
        if action_on_event and int(action_on_event):
            body.update({'ACTION_ON_EVENT': action_on_event})
        if date and str(date):
            body.update({'DATE': date})
        if time and str(time):
            body.update({'TIME': time})
        result = self.post(rel, body)
        return result

    def stop_a_running_extmue_campaign(self):
        rel = '/tmas/{}/tests/actions/stop'.format(self.tma_id)
        result = self.post(rel)
        return result

    def get_running_status_of_a_test_on_extmue(self):
        rel = '/tmas/{}/tests/actions/run'.format(self.tma_id)
        result = self.get(rel)
        return result

    def execute_mci_command_on_extmue(self, cmd, cmd_timeout=2):
        rel = '/tmas/{}/tests/actions/executecommand'.format(self.tma_id)
        body = {}
        if cmd and str(cmd):
            body.update({'MCI_COMMAND': cmd})
        if cmd_timeout and int(cmd_timeout):
            body.update({'CMD_TIMEOUT': cmd_timeout})
        result = self.post(rel, body)
        return result
